import { readFile, writeFile, mkdir, readdir } from 'node:fs/promises';
import { join } from 'node:path';
import { createHash } from 'node:crypto';
import { strict as assert } from 'node:assert';
import { replayM3, smokeFetch } from '/home/diogo/dev/testmaster/tools/dist/evals/replay.js';
const root='/home/diogo/dev/testmaster';
const output=join(root,'validation/results/m3-utility-postfix-live');
await mkdir(output,{recursive:true});
const mode=process.argv[2];
assert.ok(['first','remaining'].includes(mode));
const statePath=join(output,'session.json');
const session=mode==='first'?{development:true,registered:false,holdout:false,smoke:{calls:0,generationCalls:0,inventoryCalls:0,conservativeTokens:0,stopped:null,wire:[]},cases:[]}:JSON.parse(await readFile(statePath,'utf8'));
if(mode==='remaining')assert.equal(session.cases[0]?.accepted,true,'First case was not accepted');
const ids=mode==='first'?['m3-bug-02']:['m3-bug-03','m3-drift-03','m3-healthy-01'];
const originalFetch=globalThis.fetch;
globalThis.fetch=smokeFetch(originalFetch,session.smoke,'https://api.quantforge.com.br/v1');
const hashes=async(dir)=>{const result={};async function walk(p){for(const e of await readdir(p,{withFileTypes:true})){const file=join(p,e.name);if(e.isDirectory())await walk(file);else if(e.isFile())result[file.slice(dir.length+1)]=createHash('sha256').update(await readFile(file)).digest('hex');else throw Error('Nonregular retained entry');}}await walk(dir);return result;};
try{
 for(const id of ids){
  assert.ok(!session.cases.some(c=>c.id===id),'Duplicate paid case');
  assert.ok(session.cases.length<4);
  if(session.smoke.stopped)break;
  const ledger=JSON.parse(await readFile(join(root,'evals/results/m3-round3-qwen38-medium-2026-10-08T03-41-42-368Z',id+'.json'),'utf8'));
  const before=await hashes(ledger.records.workspace);
  let report;
  try{report=await replayM3(root,'evals/results/m3-round3-qwen38-medium-2026-10-08T03-41-42-368Z','postfix-live-'+id,{model:true,caseIds:[id]});}
  finally{assert.deepEqual(await hashes(ledger.records.workspace),before,'Original retained workspace changed');}
  const analysis=report.analyses[0];
  const row=report.ledgers[0];
  const model=analysis?.model;
  const modelSteps=model?.diagnosis?.nextSteps.filter(s=>s.source==='model')??[];
  const rejected=model?.limitations.some(l=>l.startsWith('Model enrichment abstained:'))??true;
  const preserved=!!model&&JSON.stringify(model.diagnosis.conclusion)===JSON.stringify(analysis.rules.diagnosis.conclusion)&&JSON.stringify(model.diagnosis.healing)===JSON.stringify(analysis.rules.diagnosis.healing);
  const accepted=!!model?.modelCallId&&!rejected&&preserved&&!row.errors.length&&!session.smoke.stopped&&(id==='m3-healthy-01'||modelSteps.length>0);
  const entry={id,accepted,reportDirectory:report.directory,modelCallId:model?.modelCallId??null,conclusionAndHealingPreserved:preserved,modelSteps,limitations:model?.limitations??[],utility:row.utility,usage:row.usage,calls:row.records.calls,errors:row.errors,originalByteIdentical:true};
  session.cases.push(entry);
  await writeFile(statePath,JSON.stringify(session,null,2)+'\n');
  console.log(JSON.stringify(entry,null,2));
  if(!accepted){session.stopReason='case_not_accepted';break;}
 }
}finally{
 globalThis.fetch=originalFetch;
 await writeFile(statePath,JSON.stringify(session,null,2)+'\n');
 console.log(JSON.stringify({generationCalls:session.smoke.generationCalls,inventoryCalls:session.smoke.inventoryCalls,conservativeTokens:session.smoke.conservativeTokens,stopped:session.smoke.stopped,stopReason:session.stopReason??null}));
}
